// RAW Hazard (Read After Write / True Dependency)
// I1 writes R1. I2 reads R1 before I1 WB stage completes.

I1: ADD R1, R2, R3    // Def: R1
I2: SUB R4, R1, R5    // Use: R1
I3: AND R6, R7, R8

// Hazard mitigation: Data Forwarding or pipeline stall (NOPs)
// R1 value is needed by I2 EX stage, available from I1 EX or MEM stage.

// WAW Hazard (Write After Write / Output Dependency)
// I1 and I4 both write the same destination register (R1).

I1: LOAD R1, 0(R2)    // Writes R1
I2: SUB R6, R7, R8
I3: ADD R9, R9, R10
I4: DIV R1, R11, R12  // Writes R1
// Must maintain sequential write order.

// WAR Hazard (Write After Read / Anti-Dependency)
// I1 reads R3. I3 writes R3.

I1: STORE R2, 0(R3)   // Read R3 (Address)
I2: ADD R4, R5, R6
I3: SUB R3, R7, R8    // Write R3 (Value)
// I3 must not complete WB before I1 finishes reading R3.
// Often resolved via Register Renaming.
